import {SHARING_CASES,SHARING_CONVERSATION} from './sharing-counter-content.mjs';
import {sharingState,sharingView,sharingPieces,sharingAssessment,sharingFeedback,chooseSharingCase,nextSharingCase,setSharingPage,toggleSharingCut,joinSharingLoaf,setSharingPartition,toggleSharingPiece,moveSharingBun,shareSharingRound,toggleSharingGroup,requestSharingSupport,stepSharingExample,checkSharing,keepSharing,recoverSharing} from './sharing-counter-core.mjs';
import {sharingLoafArt,sharingBunArt,sharingNumberLine,sharingEquivalenceArt,CUT_GUIDES} from './sharing-counter-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attr,id,text,on=false)=>`<button type="button" class="secondary ${on?'selected':''}" data-sc-${attr}="${id}" aria-pressed="${on}">${text}</button>`;
const pages=[['make','Make'],['compare','Compare'],['keep','Keep or revise']];
function heading(){return '<header><a class="back" href="#cafe"><span aria-hidden="true">←</span> Back to my café order</a><h1>The Sharing Counter</h1><p>Picnic parcels for the neighbors who helped after the storm.</p></header>';}
function chooser(s){return `<div class="sc-workspace">${heading()}<section class="sc-chooser"><h2 id="sc-title" tabindex="-1">Who shall we pack for?</h2><p>Cut, join, share and try a different way. Your café guest and cupboard will wait.</p><div class="sc-case-grid">${SHARING_CASES.map(c=>`<button type="button" class="secondary sc-case" data-sc-case="${c.id}"><span class="sc-case-icon" aria-hidden="true">${c.kind==='loaf'?'▰':'◌'}</span><strong>${esc(c.title)}</strong><span>${esc(c.reason)}</span>${s.cases[c.id]?'<small>Your parcel is waiting</small>':''}</button>`).join('')}</div><p class="tiny">Six picnic requests to visit again and again. The café jars stay as they are.</p></section></div>`;}
function fractionPanel(v){if(!v.fraction)return `<div class="sc-portion"><strong>${esc(v.partitionLabel)}</strong><p>${v.case.kind==='loaf'?'First make the equal shares the request asks for.':'Put the same number of buns on each mat. Use all twelve. Then pack whole groups.'}</p><p>${v.selectedCount} ${v.case.kind==='loaf'?(v.selectedCount===1?'piece':'pieces'):(v.selectedCount===1?'group':'groups')} packed so far.</p></div>`;return `<div class="sc-portion"><strong>${v.fraction.words} marked packed · ${v.fraction.notation}</strong><p>${v.case.kind==='basket'?`${v.selectedAmount} of the 12 buns are packed. The top number counts whole groups of buns.`:'Packed pieces stay in their places, so you can compare them with the whole loaf.'}</p></div>`;}
function loafModel(v,interactive=true){return `<section class="sc-model" aria-label="The whole loaf">${sharingLoafArt(v.pieces,v.model.cuts,{guides:interactive&&v.case.family==='repair'})}<p class="tiny">A pretend loaf, the same thickness all the way along. The letters mark places to cut.</p>${fractionPanel(v)}${interactive?`<div class="sc-piece-buttons" role="group" aria-label="Pack a piece or put it back">${v.pieces.map(p=>button('piece',p.index,`Piece ${p.index+1}${p.selected?' · packed':' · on the loaf'}`,p.selected)).join('')}</div>`:''}</section>`;}
function basketModel(v,interactive=true){return `<section class="sc-whole-basket" aria-label="The whole basket of twelve buns"><h3>Our whole · 12 identical buns</h3><p ${interactive?'id="sc-basket-status" tabindex="-1" role="status"':''} class="sc-basket-status">${v.work.message==='groups-returned'?esc(v.message)+' ':''}${v.tray} in the tray; groups: ${v.model.groups.join(', ')}.</p><div class="sc-unshared"><div><strong>Still to share: ${v.tray}</strong>${sharingBunArt(v.tray,'unshared buns')}</div><p>The tray and all four group mats belong to this one whole.</p></div><div class="sc-mats">${v.model.groups.map((n,i)=>`<section class="sc-mat ${v.model.selected.includes(i)?'packed':''}">${interactive?`<button type="button" class="sc-pack-mat" data-sc-group="${i}" aria-pressed="${v.model.selected.includes(i)}" ${!v.canPackGroups?'disabled':''}>`:''}<strong>Group ${i+1} · ${n} buns</strong>${sharingBunArt(n)}<span>${v.model.selected.includes(i)?'Packed <span aria-hidden="true">✓</span>':v.canPackGroups?(interactive?'Tap to pack this group':'Group on the mat'):'Group mat'}</span>${interactive?'</button>':''}${interactive?`<div class="sc-mat-actions"><button type="button" class="secondary" data-sc-bun="${i}:in" aria-label="Put one bun in group ${i+1}" ${v.tray===0?'disabled':''}>+1 here</button><button type="button" class="secondary" data-sc-bun="${i}:out" aria-label="Return one bun from group ${i+1}" ${n===0?'disabled':''}>−1 back</button></div>`:''}</section>`).join('')}</div><p class="tiny">A packed group goes into your parcel. Its buns stay in the picture, so you can still see the whole.</p>${fractionPanel(v)}</section>`;}
function model(v,interactive=true){return v.case.kind==='loaf'?loafModel(v,interactive):basketModel(v,interactive);}
function controls(v){if(v.case.family==='repair')return `<h3>Where should the cuts go?</h3><p>Tap a letter to cut or join there. Make every piece the same width.</p><div class="sc-cut-buttons" role="group" aria-label="Cut guides A through K">${CUT_GUIDES.map((g,i)=>button('cut',i+1,`<span class="sr-only">Cut at </span>${g}`,v.model.cuts.includes(i+1))).join('')}</div><button type="button" class="secondary" data-sc-join ${v.model.cuts.length?'':'disabled'}>Join the loaf again</button><p>Then tap pieces to pack them or put them back. If you change the cuts, packed pieces go back on the loaf first.</p>`;if(v.case.family==='compare')return `<h3>Same loaf, different cuts</h3><p>Choose Two equal shares or Four equal shares. Then tap the pieces to pack. The whole stays the same size.</p><div class="sc-controls">${button('partition',2,'Two equal shares',v.model.cuts.length===1)}${button('partition',4,'Four equal shares',v.model.cuts.length===3)}</div><p>If you change the cuts, packed pieces go back on the loaf first. Your kept parcels stay as they were.</p>`;return `<h3>Share the buns, then pack groups</h3><p>Put buns on any mat, or press Put one bun on each mat. Use all twelve buns. Make the four groups equal. Then pack whole groups.</p><button type="button" class="primary" data-sc-round ${v.tray<4?'disabled':''}>Put one bun on each mat</button><p>Each mat has a +1 here button and a −1 back button. When the groups are equal, tap a mat to pack its group or put it back.</p>`;}
function checkResult(v){if(v.work.message!=='checked')return v.message?`<p id="sc-feedback" class="sc-feedback" tabindex="-1" role="status">${esc(v.message)}</p>`:'';const a=v.work.checks.at(-1).assessment;return `<section id="sc-feedback" class="sc-feedback" tabindex="-1" role="status"><h3>Look at this arrangement</h3><p>${esc(sharingFeedback(v.case,a))}</p><ul><li>Number of shares: ${a.shareCountFit?'fits this request':'try the requested number'}</li><li>Equal sizes: ${a.shareCount<2?'make several shares to compare':a.equalSizes?'yes':'not yet'}</li>${v.case.kind==='basket'?`<li>All buns shared into mats: ${a.allAccounted?'yes':'some still in the tray'}</li>`:''}<li>${v.case.family==='repair'?'Pieces packed':v.case.kind==='basket'?'Whole groups packed':'Amount of the whole packed'}: ${a.portionFit?'fits this request':'try another portion'}</li></ul></section>`;}
function example(v){const w=v.work,step=w.exampleStep??0;if(v.case.id==='half-parcel'&&w.support.equivalence)return `<section class="sc-example"><h3>One half and two quarters</h3>${sharingEquivalenceArt(step)}<p>${step===0?'The whole outlines are identical. One has two equal pieces; the other has four.':step===1?'One of the two shares and two of the four shares cover the same amount.':'Different cuts. The same amount packed from the same whole.'}</p>${exampleButtons(step)}</section>`;if(v.case.kind==='basket'&&w.support.workedExample)return `<section class="sc-example"><h3>A different basket · 8 buns</h3>${step===0?`${sharingBunArt(8)}<p>Start with eight buns and two empty group mats. Share them equally.</p>`:`<div class="sc-example-groups">${[0,1].map(i=>`<div class="${step===2&&i===0?'packed':''}"><strong>Group ${i+1} · 4 buns</strong>${sharingBunArt(4)}</div>`).join('')}</div><p>Two equal groups of four make eight buns. ${step===2?'One whole group is half of this example basket: four buns.':'Each group is one of two equal shares.'}</p>`}<p class="tiny">Your twelve-bun basket stays as it is.</p>${exampleButtons(step)}</section>`;return '';}
function exampleButtons(step){return `<div class="sc-controls"><button type="button" class="secondary" data-sc-example="-1" ${step===0?'disabled':''}>Previous picture</button><span>Picture ${step+1} of 3</span><button type="button" class="secondary" data-sc-example="1" ${step===2?'disabled':''}>Next picture</button></div>`;}
function comparison(v){if(v.case.kind==='loaf')return `<h2 id="sc-title" tabindex="-1">How much is packed?</h2><p>A part only makes sense beside its whole. Keep the whole loaf in view.</p>${v.linePosition===null?'<p>Make the equal shares first. Then the strip can show the fraction.</p>':`<h3>A matching strip and number line</h3>${sharingNumberLine(v.linePosition)}<p>The strip puts the packed pieces side by side. The marker shows how much is packed.</p>`}${v.case.id==='half-parcel'?'<button type="button" class="secondary" data-sc-support="equivalence">Show one half and two quarters of the same whole</button>':''}<button type="button" class="secondary" data-sc-support="notation">Read the fraction words</button>${v.work.support.notation?`<p>${v.fraction?`${v.fraction.notation} means ${v.fraction.words} from this whole.`:'Make equal pieces first. Quarters are four pieces of the same width.'}</p>`:''}`;return `<h2 id="sc-title" tabindex="-1">A fraction of a basket</h2><p>Our whole is all twelve buns. The four mats help us make four equal groups.</p><button type="button" class="secondary" data-sc-support="notation">Explain the groups and buns</button>${v.work.support.notation?`<p>${v.canPackGroups?`Four equal groups of three make twelve buns. ${v.selectedCount} of the four groups are marked packed: ${v.selectedAmount} buns.${v.selectedCount===1?' One quarter of twelve is three buns.':v.selectedCount===3?' Three quarters of twelve is nine buns.':''}`:'First make four equal groups with all twelve buns. Then each mat holds one quarter of the whole.'}</p>`:''}<button type="button" class="secondary" data-sc-support="workedExample">See a different eight-bun example</button>`;}
function keptView(snapshot){const c=snapshot.source,a=sharingAssessment(c,snapshot.model),pieces=c.kind==='loaf'?sharingPieces(snapshot.model):[],selectedAmount=c.kind==='loaf'?pieces.filter(p=>p.selected).reduce((n,p)=>n+p.width,0):snapshot.model.selected.reduce((n,i)=>n+snapshot.model.groups[i],0),valid=a.shareCountFit&&a.equalSizes&&a.allAccounted;return {case:c,work:{...snapshot,checks:[]},model:snapshot.model,pieces,assessment:a,tray:c.kind==='basket'?12-snapshot.model.groups.reduce((a,b)=>a+b,0):null,selectedCount:snapshot.model.selected.length,selectedAmount,fraction:valid?{words:`${snapshot.model.selected.length} of ${c.kind==='loaf'?pieces.length:4} equal shares`,notation:`${snapshot.model.selected.length}/${c.kind==='loaf'?pieces.length:4}`} :null,partitionLabel:c.kind==='basket'?'four group mats':`${pieces.length} ${a.equalSizes?'pieces':'unequal pieces'}`,canPackGroups:c.kind==='basket'&&valid};}
function task(s,v){if(s.page==='make')return `<h2 id="sc-title" tabindex="-1">Let’s make this parcel</h2>${controls(v)}<button type="button" class="primary" data-sc-check>Look at my parcel</button>${checkResult(v)}<p><button type="button" class="secondary" data-sc-page="compare">Compare the part and whole <span aria-hidden="true">→</span></button></p>`;if(s.page==='compare')return `${comparison(v)}${checkResult(v)}<p><button type="button" class="primary" data-sc-page="keep">Keep or change this parcel <span aria-hidden="true">→</span></button></p>`;return `<h2 id="sc-title" tabindex="-1">Keep an idea for the picnic</h2>${checkResult(v)}<p>An unfinished or unusual arrangement can be worth keeping. You can come back and change it.</p><button type="button" class="primary" data-sc-keep>Keep this picnic parcel</button><button type="button" class="secondary" data-sc-page="make">Change my parcel</button>${v.work.kept?`<section class="sc-kept" id="sc-kept" tabindex="-1"><h3>Your kept draft</h3><p>${esc(v.work.kept.source.request)}</p>${model(keptView(v.work.kept),false)}<p class="tiny">Your parcel is saved just as it was.</p><details class="grownup-note"><summary>For grown-ups</summary><p>A kept parcel saves its whole, arrangement and the help in use. ${v.work.kept.latestCheck?'The last check is saved separately and may describe an earlier arrangement.':'No check is saved with this parcel.'} Keeping a parcel is separate from café serving, and it is not a grade.</p></details></section>`:''}<h3>Wonder together</h3>${SHARING_CONVERSATION.map(t=>`<p>${t}</p>`).join('')}<p class="tiny">Tell, point or draw.</p><details class="grownup-note"><summary>For grown-ups</summary><p>The game does not record or judge this conversation.</p></details>`;}
export function sharingCounterEntry(){return '<aside class="sc-entry"><div><h2>Pack a picnic, piece by piece</h2><p>Fix loaf slices, discover another way to make half, and share a basket of buns.</p></div><a class="secondary" href="#cafe/sharing">Visit the Sharing Counter <span aria-hidden="true">→</span></a></aside>';}
export function sharingCounterPage(state){const s=sharingState(state);if(!s)return `${heading()}<section class="panel"><h2 id="sc-title" tabindex="-1">An earlier picnic draft is kept</h2><p>This format cannot be opened here. Its exact record remains in notes downloads.</p><button type="button" class="secondary" data-sc-recover>Keep the earlier record and continue</button></section>`;if(s.page==='choose'||!s.currentCase)return chooser(s);const v=sharingView(state);return `<div class="sc-workspace">${heading()}<section class="sc-request"><strong>${esc(v.case.reader)}</strong><p>${esc(v.case.reason)}</p><h2>${esc(v.case.request)}</h2>${v.work.familiar?'<span class="tiny">Your parcel is waiting.</span>':''}</section><nav class="sc-pages" aria-label="Sharing Counter task">${pages.map(([id,label],i)=>button('page',id,`${i+1}. ${label}`,s.page===id)).join('')}<button type="button" class="text-button" data-sc-page="choose">Other requests</button></nav><div class="sc-layout"><div class="sc-picture">${model(v)}</div><section class="sc-task">${task(s,v)}</section></div><aside class="sc-support"><div class="sc-controls"><button type="button" class="secondary" data-sc-support="together" aria-pressed="${!!v.work.support.together}">${v.work.support.together?'We’re working together <span aria-hidden="true">✓</span>':'We’re working together'}</button><span data-sc-audio>${hearButton(`${v.case.reason} ${v.case.request} ${s.page==='make'?'You can change the arrangement and try again.':s.page==='compare'?'Keep the whole in view while comparing its parts.':'Keep an unfinished idea or change it.'}`,'Hear this turn')}</span></div>${example(v)}</aside><div class="sc-footer"><button type="button" class="secondary" data-sc-next>Another picnic request</button><a href="#cafe/groups">Explore the equal-group bench</a><a href="#cafe">Return to my café guest</a><a href="#notes">Grown-up notes</a></div><p class="tiny">Imaginary food in a picture. The café jars stay as they are.</p></div>`;}
export function bindSharingCounter(state,ctx){const refresh=(target='#sc-title')=>{ctx.save();ctx.render();ctx.focus?.(target);};const act=(fn,target)=>{if(fn())refresh(target);};document.querySelectorAll('[data-sc-case]').forEach(b=>b.onclick=()=>act(()=>chooseSharingCase(state,b.dataset.scCase)));document.querySelectorAll('[data-sc-page]').forEach(b=>b.onclick=()=>act(()=>setSharingPage(state,b.dataset.scPage)));document.querySelector('[data-sc-next]')?.addEventListener('click',()=>act(()=>nextSharingCase(state)));document.querySelectorAll('[data-sc-cut]').forEach(b=>b.onclick=()=>act(()=>toggleSharingCut(state,Number(b.dataset.scCut)),`[data-sc-cut="${b.dataset.scCut}"]`));document.querySelector('[data-sc-join]')?.addEventListener('click',()=>act(()=>joinSharingLoaf(state),'#sc-title'));document.querySelectorAll('[data-sc-partition]').forEach(b=>b.onclick=()=>act(()=>setSharingPartition(state,Number(b.dataset.scPartition)),`[data-sc-partition="${b.dataset.scPartition}"]`));document.querySelectorAll('[data-sc-piece]').forEach(b=>b.onclick=()=>act(()=>toggleSharingPiece(state,Number(b.dataset.scPiece)),`[data-sc-piece="${b.dataset.scPiece}"]`));document.querySelectorAll('[data-sc-bun]').forEach(b=>b.onclick=()=>{const [i,d]=b.dataset.scBun.split(':');if(moveSharingBun(state,Number(i),d)){const v=sharingView(state),sameEnabled=d==='in'?v.tray>0:v.model.groups[Number(i)]>0;refresh(`[data-sc-bun="${i}:${sameEnabled?d:d==='in'?'out':'in'}"]`);}});document.querySelector('[data-sc-round]')?.addEventListener('click',()=>{if(shareSharingRound(state)){refresh(sharingView(state).tray>=4?'[data-sc-round]':'#sc-basket-status');}});document.querySelectorAll('[data-sc-group]').forEach(b=>b.onclick=()=>act(()=>toggleSharingGroup(state,Number(b.dataset.scGroup)),`[data-sc-group="${b.dataset.scGroup}"]`));document.querySelector('[data-sc-check]')?.addEventListener('click',()=>act(()=>checkSharing(state),'#sc-feedback'));document.querySelectorAll('[data-sc-support]').forEach(b=>b.onclick=()=>act(()=>requestSharingSupport(state,b.dataset.scSupport),['equivalence','workedExample'].includes(b.dataset.scSupport)?'.sc-example':b.dataset.scSupport==='notation'?'#sc-title':'.sc-support'));document.querySelectorAll('[data-sc-example]').forEach(b=>b.onclick=()=>act(()=>stepSharingExample(state,Number(b.dataset.scExample)),'.sc-example'));document.querySelectorAll('[data-sc-audio] [data-speak]').forEach(b=>b.addEventListener('click',()=>{requestSharingSupport(state,'audio');ctx.save();}));document.querySelector('[data-sc-keep]')?.addEventListener('click',()=>act(()=>keepSharing(state),'#sc-kept'));document.querySelector('[data-sc-recover]')?.addEventListener('click',()=>act(()=>recoverSharing(state)));}
export function sharingCounterNotes(state){if(!Object.hasOwn(state,'sharingCounter'))return '';return `<details class="panel" data-sc-notes><summary>Sharing Counter: wholes, shares and picnic drafts</summary><p>Picture practice with six fixed fraction requests. Share counts, equal sizes, amount packed, pictures, moving pieces, check feedback, examples, fraction words, listening and working together are recorded separately. Kept parcels are saved ideas, separate from café serving, and they are not grades. Only equal groups actually shown on screen count toward multiplication familiarity.</p><pre>${esc(JSON.stringify(state.sharingCounter,null,2))}</pre></details>`;}
